export default class CsvWriter {
  // The entry point for the worker
  init(data) {
    this.data = data;
  }

  start() {
    // Generate CSV string
    const headers = this.data[0] ? Object.keys(this.data[0]) : [];
    let csv = headers.join(',') + '\n';

    for (const row of this.data) {
      const rowValues = headers.map((header) => {
        // Escape quotes and commas for safety
        let val = String(row[header] || '');
        if (val.includes(',') || val.includes('"') || val.includes('\n')) {
          val = `"${val.replace(/"/g, '""')}"`;
        }
        return val;
      });
      csv += rowValues.join(',') + '\n';
    }

    return csv;
  }
}
```

